    return [
        {
            "title": f"{['Alpha', 'Beta', 'Gamma', 'Delta', 'Echo'][i % 5]} #{i}",
            "body": f"Deterministic note {i}. Unicode: café 世界. seed={seed}",
            "tags": sorted({rng.choice(tags) for _ in range(2)}),
        }
        for i in range(1, count + 1)
    ]

